-- Data for Name: Vocabulary; Type: TABLE DATA; Schema: cam; Owner: -
--

COPY cam."Vocabulary" (vocabulary_prefix, name, vocabulary_uri, vocabulary_id, fhir_system, description, version, vocabulary_source) FROM stdin;
CAMO	Common Access Model Ontology	http://purl.obolibrary.org/obo/CAMO_	\N	http://purl.obolibrary.org/obo/CAMO	Organized terms in support of a shared data model.	\N	\N
CDCREC	CDC Rec	https://cdc.gov#	\N	urn:oid:2.16.840.1.113883.6.238	The U.S. Centers for Disease Control and Prevention (CDC) has prepared a code set for use in coding race and ethnicity data. This code set is based on current federal standards for classifying data on race and ethnicity, specifically the minimum race and ethnicity categories defined by the U.S. Office of Management and Budget (OMB) and a more detailed set of race and ethnicity categories maintained by the U.S. Bureau of the Census (BC).	\N	\N
DUO	Data Use Ontology	http://purl.obolibrary.org/obo/DUO_	\N	http://purl.obolibrary.org/obo/duo.owl	DUO is an ontology which represent data use conditions.	\N	\N
HP	Human Phenotype Ontology	http://purl.obolibrary.org/obo/HP_	\N	http://purl.obolibrary.org/obo/hp.owl	The Human Phenotype Ontology (HPO) aims to provide a standardized vocabulary of phenotypic abnormalities encountered in human disease. Each term in the HPO describes a phenotypic abnormality, such as atrial septal defect. The HPO is currently being developed using the medical literature, Orphanet, DECIPHER, and OMIM.	\N	\N
KIN	KIN - The Family History Relations Ontology	http://purl.org/ga4gh/kin.owl#KIN_	\N	http://purl.org/ga4gh/kin.owl	KIN is a family relations ontology developed as part of the Global Alliance for Genomics and Health Pedigree Standard project. It allows using an OWL reasoner to automatically validate a family history graph and infer new relations.	\N	\N
MONDO	Mondo Disease Ontology	http://purl.obolibrary.org/obo/MONDO_	\N	http://purl.obolibrary.org/obo/mondo.owl	The Mondo Disease Ontology (Mondo) aims to harmonize disease definitions across the world.	\N	\N
MS	Mass spectrometry ontology	http://purl.obolibrary.org/obo/MS_	\N	http://purl.obolibrary.org/obo/ms.owl	The PSI-Mass Spectrometry (MS) CV contains all the terms used in the PSI MS-related data standards. The CV contains a logical hierarchical structure to ensure ease of maintenance and the development of software that makes use of complex semantics. The CV contains terms required for a complete description of an MS analysis pipeline used in proteomics, including sample labeling, digestion enzymes, instrumentation parts and parameters, software used for identification and quantification of peptides/proteins and the parameters and scores used to determine their significance.	\N	\N
NCIT	National Cancer Institute Thesaurus	http://purl.obolibrary.org/obo/NCIT_	\N	http://purl.obolibrary.org/obo/ncit.owl	NCI Thesaurus (NCIt) provides reference terminology covering vocabulary for clinical care, translational and basic research, and public information and administrative activities, providing a stable and unique identification code.	\N	\N
OBI	Ontology for Biomedical Investigations	http://purl.obolibrary.org/obo/OBI_	\N	http://purl.obolibrary.org/obo/obi.owl	The Ontology for Biomedical Investigations (OBI) project is developing an integrated ontology for the description of biological and clinical investigations. The ontology will represent the design of an investigation, the protocols and instrumentation used, the material used, the data generated and the type analysis performed on it. Currently OBI is being built under the Basic Formal Ontology (BFO).	\N	\N
UBERON	Uber Anatomy Ontology	http://purl.obolibrary.org/obo/UBERON_	\N	http://purl.obolibrary.org/obo/uberon.owl	Uberon is an integrated cross-species anatomy ontology representing a variety of entities classified according to traditional anatomical criteria such as structure, function and developmental lineage. The ontology includes comprehensive relationships to taxon-specific anatomical ontologies, allowing integration of functional, phenotype and expression data.	\N	\N
edam	EDAM Ontology	http://edamontology.org/	\N	http://edamontology.org/	EDAM is an ontology of general bioinformatics concepts, including topics, data types, formats, identifiers and operations. EDAM provides a controlled vocabulary for the description, in semantic terms, of things such as: web services (e.g. WSDL files), applications, tool collections and packages, work-benches and workflow software, databases and ontologies, XSD data schema and data objects, data syntax and file formats, web portals and pages, resource catalogues and documents (such as scientific publications).	\N	\N
loinc	Logical Observation Identifiers Names and Codes	https://loinc.org/rdf/	\N	http://loinc.org	The international standard for identifying health measurements, observations, and documents.	\N	\N
mesh	Medical Subject Headings	http://id.nlm.nih.gov/mesh/	\N	http://terminology.hl7.org/CodeSystem/MSH	MeSH (Medical Subject Headings) is the National Library of Medicine's controlled vocabulary thesaurus. It consists of sets of terms naming descriptors in a hierarchical structure that permits searching at various levels of specificity. This thesaurus is used by NLM for indexing articles from biomedical journals, cataloguing of books, documents, etc.	\N	\N
snomedct	Systematized Nomenclature of Medicine - Clinical Terms	http://snomed.info/id/	\N	http://snomed.info/sct	SNOMED CT (Systematized Nomenclature of Medicine -- Clinical Terms), is a systematically organized computer processable collection of medical terminology covering most areas of clinical information such as diseases, findings, procedures, microorganisms, pharmaceuticals, etc.	\N	\N
ucum	Unified Code for Units of Measure	https://units-of-measurement.org/	\N	http://unitsofmeasure.org	Unified Code for Units of Measure (UCUM) is a code system intended to include all units of measures being contemporarily used in international science, engineering, and business.	\N	\N
\.


